import sys
from abc import ABC, abstractmethod

class Employee(ABC):
    def __init__(self, name, emp_id, base_salary):
        self.__name = name
        self.__id = emp_id
        self.__base_salary = base_salary

    def getName(self):
        return self.__name

    def getId(self):
        return self.__id

    def getBaseSalary(self):
        return self.__base_salary

    @abstractmethod
    def calculateSalary(self):
        pass

class FullTimeEmployee(Employee):
    def calculateSalary(self):
        return self.getBaseSalary() * 1.2

class PartTimeEmployee(Employee):
    def calculateSalary(self):
        return self.getBaseSalary()

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 4:
            continue

        emp_type = int(parts[0])
        name = parts[1]
        emp_id = int(parts[2])
        base_salary = float(parts[3])

        if emp_type == 1:
            employee = FullTimeEmployee(name, emp_id, base_salary)
        else:
            employee = PartTimeEmployee(name, emp_id, base_salary)

        print(f"Employee Name: {employee.getName()}")
        print(f"Employee ID: {employee.getId()}")
        print(f"Final Salary: {employee.calculateSalary():.2f}")

if __name__ == "__main__":
    main()
